CREATE OR REPLACE FUNCTION sappo_destination(name TEXT,lat DOUBLE PRECISION,lng DOUBLE PRECISION)
RETURNS TEXT LANGUAGE SQL IMMUTABLE AS $$
 SELECT CASE
 WHEN LOWER(REPLACE(REPLACE(TRIM(name),'-',' '),'_',' ')) IN ('liverpool','liverpool area','waterloo','frodsham') THEN 'Liverpool'
 WHEN LOWER(REPLACE(REPLACE(TRIM(name),'-',' '),'_',' ')) IN ('manchester','manchester area','greater manchester') THEN 'Manchester'
 WHEN LOWER(REPLACE(REPLACE(TRIM(name),'-',' '),'_',' ')) IN ('barcelona','barcelona area') THEN 'Barcelona'
 WHEN LOWER(REPLACE(REPLACE(TRIM(name),'-',' '),'_',' ')) IN ('wales','dolgellau','dolgellau area') OR sappo_in_wales(lat,lng) THEN 'Wales'
 ELSE name END
$$;
DO $$ DECLARE before_count BIGINT; after_count BIGINT; BEGIN
SELECT COUNT(*) INTO before_count FROM venues;
UPDATE venues SET source_locality=COALESCE(source_locality,city),city=sappo_destination(city,lat,lng)
WHERE city IS DISTINCT FROM sappo_destination(city,lat,lng);
SELECT COUNT(*) INTO after_count FROM venues;
IF before_count <> after_count THEN RAISE EXCEPTION 'Destination recategorisation changed venue count'; END IF;
END $$;
COMMIT;
